using System.Data;
using System.Data.Common;
using PA.Tickets.Migration026Runner;

public sealed class Migration026RunnerTests
{
    [Fact] public void Canonical_selection_rejects_alternate_paths() { var path = Migration026Runner.ResolveCandidatePath(); Assert.EndsWith(Migration026Runner.CandidateRelativePath.Replace('/', Path.DirectorySeparatorChar), path, StringComparison.OrdinalIgnoreCase); Assert.Throws<InvalidOperationException>(() => Migration026Runner.ValidateCanonicalPath(Path.Combine(Path.GetDirectoryName(path)!, "other.sql"))); Assert.Throws<InvalidOperationException>(() => Migration026Runner.ValidateCanonicalPath(Path.Combine(Path.GetDirectoryName(path)!, "..", "026_phase8_6_reporting.review.v3.sql"))); }
    [Fact] public async Task Exact_candidate_bytes_are_hashed_and_passed_unchanged() { var c = await Migration026Runner.ReadAndValidateCandidateAsync(); Assert.Equal(c.Bytes, System.Text.Encoding.UTF8.GetBytes(c.Sql)); }
    [Fact] public async Task Policy_is_required_before_connection() { var fake = new FakeConnection(); var runner = new Migration026Runner(_ => { fake.Connected = true; return Task.FromResult<ITargetConnection>(fake); }, new NoExecutionPolicy()); await Assert.ThrowsAsync<InvalidOperationException>(() => runner.ExecuteAsync(new(Migration026Runner.CandidateHash, "fp", "auth"))); Assert.False(fake.Connected); }
    [Fact] public async Task Target_mismatch_happens_before_transaction_or_lock() { var fake = new FakeConnection(); var runner = NewRunner(fake, new FakePolicy("different")); await Assert.ThrowsAsync<InvalidOperationException>(() => runner.ExecuteAsync(new(Migration026Runner.CandidateHash, "approved", "auth"))); Assert.Equal(0, fake.BeginCount); Assert.Equal(0, fake.LockCount); }
    [Fact] public async Task Precommit_failure_rolls_back_and_preserves_failure() { var fake = new FakeConnection { ExecuteError = new InvalidOperationException("migration failed") }; var runner = NewRunner(fake); var ex = await Assert.ThrowsAsync<InvalidOperationException>(() => runner.ExecuteAsync(new(Migration026Runner.CandidateHash, "fp", "auth"))); Assert.Equal("migration failed", ex.Message); Assert.Equal(1, fake.Rollbacks); Assert.Equal(ExecutionState.RolledBack, runner.State); }
    [Fact] public async Task Rollback_failure_preserves_both_failures() { var fake = new FakeConnection { ExecuteError = new InvalidOperationException("migration failed"), RollbackError = new InvalidOperationException("rollback failed") }; var runner = NewRunner(fake); var ex = await Assert.ThrowsAsync<RollbackFailureException>(() => runner.ExecuteAsync(new(Migration026Runner.CandidateHash, "fp", "auth"))); Assert.Contains("migration failed", ex.ToString()); Assert.Contains("rollback failed", ex.ToString()); Assert.Equal(ExecutionState.UnknownCommit, runner.State); }
    [Fact] public async Task Ambiguous_commit_is_unknown_and_not_retryable() { var fake = new FakeConnection { CommitError = new InvalidOperationException("connection lost") }; var runner = NewRunner(fake); await Assert.ThrowsAsync<UnknownCommitException>(() => runner.ExecuteAsync(new(Migration026Runner.CandidateHash, "fp", "auth"))); Assert.Equal(ExecutionState.UnknownCommit, runner.State); await Assert.ThrowsAsync<InvalidOperationException>(() => runner.ExecuteAsync(new(Migration026Hash(), "fp", "auth"))); Assert.Equal(1, fake.ExecuteCount); }
    [Fact] public void Candidate_hash_is_fixed() => Assert.Equal("97EB600B6B7F1D73985A28703CA0337A59F42F14A7EFB7FEA557F468638DAE49", Migration026Runner.CandidateHash);
    private static string Migration026Hash() => Migration026Runner.CandidateHash;
    private static Migration026Runner NewRunner(FakeConnection fake, FakePolicy? policy = null) => new(_ => Task.FromResult<ITargetConnection>(fake), policy ?? new FakePolicy("fp"));
    private sealed class FakePolicy(string fingerprint) : IExecutionPolicy { public void ValidateAuthorization(RunnerOptions options) { if (options.Authorization != "auth") throw new InvalidOperationException("authorization rejected"); } public Task<string?> VerifyActualTargetFingerprintAsync(ITargetConnection _, CancellationToken __) => Task.FromResult<string?>(fingerprint); }
    private sealed class FakeConnection : ITargetConnection { public Exception? ExecuteError, RollbackError, CommitError; public bool Connected; public int BeginCount, LockCount, ExecuteCount, Rollbacks; public ValueTask DisposeAsync()=>ValueTask.CompletedTask; public Task<DbTransaction> BeginTransactionAsync(CancellationToken _){BeginCount++; return Task.FromResult<DbTransaction>(new FakeTransaction(this));} public Task AcquireMigrationLockAsync(DbTransaction _, CancellationToken __){LockCount++; return Task.CompletedTask;} public Task ExecuteAsync(ReadOnlyMemory<byte> _, DbTransaction __, CancellationToken ___){ExecuteCount++; if(ExecuteError is not null) throw ExecuteError; return Task.CompletedTask;} }
    private sealed class FakeTransaction(FakeConnection owner) : DbTransaction { public override IsolationLevel IsolationLevel=>IsolationLevel.ReadCommitted; protected override DbConnection? DbConnection=>null; public override void Commit()=>throw owner.CommitError??new NotSupportedException(); public override void Rollback(){if(owner.RollbackError is not null) throw owner.RollbackError; owner.Rollbacks++;} public override Task CommitAsync(CancellationToken ct=default)=>owner.CommitError is null?Task.CompletedTask:Task.FromException(owner.CommitError); public override Task RollbackAsync(CancellationToken ct=default){if(owner.RollbackError is not null) return Task.FromException(owner.RollbackError); owner.Rollbacks++; return Task.CompletedTask;} }
}
